import os
from typing import Dict, Any, Optional
import boto3
from botocore.exceptions import ClientError

class StructuredDocumentExtractor:
    def __init__(self):
        self.client = boto3.client(
            'textract',
            aws_access_key_id=os.getenv('AWS_ACCESS_KEY_ID'),
            aws_secret_access_key=os.getenv('AWS_SECRET_ACCESS_KEY'),
            region_name=os.getenv('AWS_REGION', 'us-east-1')
        )

    def extract_and_validate_document(
        self,
        document_bytes: bytes,
        required_fields: Dict[str, float]
    ) -> Dict[str, Any]:
        """
        Extracts structured data from a document using Amazon Textract and validates
        required fields with their minimum confidence scores.

        Args:
            document_bytes: The document image or PDF in bytes.
            required_fields: Dictionary of field names and their minimum confidence scores (0.0-1.0).

        Returns:
            Dictionary containing:
            - 'extracted_data': All extracted key-value pairs with their confidence scores
            - 'validation_results': Dictionary of required fields with pass/fail status
            - 'missing_fields': List of required fields not found in the document
            - 'low_confidence_fields': List of fields below required confidence threshold
        """
        try:
            response = self.client.analyze_document(
                Document={'Bytes': document_bytes},
                FeatureTypes=['FORMS']
            )

            extracted_data = {}
            validation_results = {}
            missing_fields = []
            low_confidence_fields = []

            # Process key-value pairs from Textract response
            for item in response.get('Blocks', []):
                if item['BlockType'] == 'KEY_VALUE_SET' and item['EntityTypes'][0] == 'KEY':
                    key = None
                    value = None
                    key_confidence = 0.0
                    value_confidence = 0.0

                    for relationship in item.get('Relationships', []):
                        if relationship['Type'] == 'VALUE':
                            for value_id in relationship['Ids']:
                                value_block = next(
                                    (b for b in response['Blocks'] if b['Id'] == value_id),
                                    None
                                )
                                if value_block:
                                    value = value_block.get('Text', '')
                                    value_confidence = value_block.get('Confidence', 0.0) / 100.0
                        elif relationship['Type'] == 'CHILD':
                            for child_id in relationship['Ids']:
                                child_block = next(
                                    (b for b in response['Blocks'] if b['Id'] == child_id),
                                    None
                                )
                                if child_block and child_block['BlockType'] == 'WORD':
                                    key = (key or '') + child_block.get('Text', '') + ' '
                                    key_confidence = child_block.get('Confidence', 0.0) / 100.0

                    if key:
                        key = key.strip()
                        extracted_data[key] = {
                            'value': value,
                            'confidence': (key_confidence + value_confidence) / 2
                        }

            # Validate required fields
            for field, min_confidence in required_fields.items():
                if field not in extracted_data:
                    missing_fields.append(field)
                    validation_results[field] = False
                else:
                    field_confidence = extracted_data[field]['confidence']
                    if field_confidence < min_confidence:
                        low_confidence_fields.append({
                            'field': field,
                            'required_confidence': min_confidence,
                            'actual_confidence': field_confidence
                        })
                        validation_results[field] = False
                    else:
                        validation_results[field] = True

            return {
                'extracted_data': extracted_data,
                'validation_results': validation_results,
                'missing_fields': missing_fields,
                'low_confidence_fields': low_confidence_fields
            }

        except ClientError as e:
            raise Exception(f"Amazon Textract error: {e.response['Error']['Message']}")
